# 카나리 배포 판정 — 새 모델 버전에 트래픽 10% 를 주고 옛 버전과 견준다(가상 값)
stable = {"req": 9000, "err": 9, "p95_ms": 120}
canary = {"req": 1000, "err": 4, "p95_ms": 180}

def verdict(s, c, err_ratio_max=2.0, latency_ratio_max=1.3):
    er_s, er_c = s["err"] / s["req"], c["err"] / c["req"]
    lat = c["p95_ms"] / s["p95_ms"]
    reasons = []
    if er_c > er_s * err_ratio_max:
        reasons.append(f"오류율 {er_c:.2%} > 기존 {er_s:.2%} x {err_ratio_max}")
    if lat > latency_ratio_max:
        reasons.append(f"p95 지연 {lat:.2f}배 > {latency_ratio_max}")
    return ("롤백", reasons) if reasons else ("다음 단계(25%)", [])

print(verdict(stable, canary))

# 모델 가중치를 GPU 에 올릴 때 드는 메모리 어림 — 파라미터 수 x 자료형 바이트
def weights_gb(params_b, bytes_per):
    return params_b * 1e9 * bytes_per / 1024**3

for name, p in [("비전 검사 0.3B", 0.3), ("LLM 8B", 8), ("LLM 70B", 70)]:
    row = [f"{k} {weights_gb(p, b):.1f}GB" for k, b in [("fp16", 2), ("int8", 1), ("int4", 0.5)]]
    print(name, "|", " · ".join(row))
